/**
 * Data definitions shared across layers. Database models are generated by Prisma
 * (see prisma/schema.prisma); these are the application-level shapes.
 */

import type { UserType } from '@prisma/client';
import type { PageMeta } from '../utils/helpers';

/** The authenticated principal attached to each request. */
export interface AuthUser {
  id: number;
  name: string;
  email: string | null;
  mobile: string;
  userType: UserType;
  roles: string[];
  permissions: string[];
  branchId: number | null;
  isSuperAdmin: boolean;
  isCompanyWide: boolean;
  customerId: number | null;
  staffId: number | null;
}

export interface RequestMeta {
  ip?: string;
  userAgent?: string;
}

export interface Paginated<T> {
  items: T[];
  meta: PageMeta;
}

export interface ListQuery {
  page?: number;
  pageSize?: number;
  search?: string;
  sortBy?: string;
  sortOrder?: 'asc' | 'desc';
  branchId?: number;
}

export interface TokenPair {
  accessToken: string;
  refreshToken: string;
  accessTokenExpiresAt: string;
  refreshTokenExpiresAt: string;
}

export interface AccessTokenPayload {
  sub: string;
  typ: UserType;
}

export interface UploadedFileInfo {
  path: string;
  mimeType: string;
  size: number;
}

export interface TechnicianSuggestion {
  staffId: number;
  userId: number;
  name: string;
  mobile: string;
  staffCode: string;
  score: number;
  reasons: string[];
  activeJobs: number;
  jobsOnDate: number;
  matchedSkills: string[];
  coversArea: boolean;
  isAvailable: boolean;
}

export interface InvoiceLineInput {
  serviceId?: number | null;
  /** Set when the line bills a stock item; its quantity is deducted from stock. */
  stockItemId?: number | null;
  description: string;
  quantity: number;
  rate: number;
  discount?: number;
  gstRate?: number;
}

export interface InvoiceTotals {
  lines: Array<InvoiceLineInput & { amount: number; gstRate: number; discount: number }>;
  subtotal: number;
  discount: number;
  taxableAmount: number;
  cgst: number;
  sgst: number;
  igst: number;
  gstTotal: number;
  roundOff: number;
  grandTotal: number;
}

export interface ShareLink {
  channel: 'WHATSAPP';
  url: string;
  message: string;
  /** Signed, expiring public PDF link (invoice shares only). */
  pdfUrl?: string;
}
